import{_ as a,C as r,o as n,c as i,j as t,a as o,E as l,a2 as h}from"./chunks/framework.BxGh02fV.js";const y=JSON.parse('{"title":"Creation assistant","description":"","frontmatter":{"title":"Creation assistant"},"headers":[],"relativePath":"en/guide/create.md","filePath":"en/guide/create.md"}'),d={name:"en/guide/create.md"};function c(p,e,g,f,u,m){const s=r("Capture");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"creation-assistant",tabindex:"-1"},[o("Creation assistant "),t("a",{class:"header-anchor",href:"#creation-assistant","aria-label":'Permalink to "Creation assistant"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("The creation assistant bootstraps a new Effortless project step by step: the project itself, the LLM routing profile, the technical stack, an initial structure, then the deployment into your AI tools. Open it from the picker, with "),t("strong",null,"Creation assistant"),o(".")],-1)),e[2]||(e[2]=t("p",null,[o("To simply initialize a folder, with no assistant, use "),t("strong",null,"Create…"),o(" in the picker ("),t("a",{href:"/Effortless/en/guide/start.html"},"Open a workspace"),o(").")],-1)),l(s,{name:"assistant-creation",alt:"The creation assistant, step 1 Project: project path, name and description"}),e[3]||(e[3]=h('<p>Before you start, decide on the work mode and the code layout: see <a href="/Effortless/en/guide/setup.html">Choosing your setup</a>.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>At the top</strong>: five numbered steps, <strong>Project</strong>, <strong>Provider</strong>, <strong>Stack</strong>, <strong>Scaffold</strong> and <strong>Deployment</strong>. A completed step is marked.</li><li><strong>In the middle</strong>: the current step, with its title and what it does.</li><li><strong>At the bottom</strong>: <strong>Cancel</strong> and <strong>Back</strong> on the left; <strong>Later</strong> (to skip an optional step) and <strong>Next</strong> on the right, then <strong>Finish</strong> on the last step.</li></ul><p>Each step really acts when you click its button: the result message shows below the button, or the error in red.</p><h2 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h2><h3 id="_1-project" tabindex="-1">1. Project <a class="header-anchor" href="#_1-project" aria-label="Permalink to &quot;1. Project&quot;">​</a></h3><ol><li>Enter the <strong>Project path</strong>, or pick the folder with <strong>Browse…</strong>.</li><li>Give a <strong>Project name</strong>, and if you like a <strong>Description (optional)</strong>.</li><li>Click <strong>Initialize project</strong>.</li></ol><p>This step is required: <strong>Next</strong> stays greyed out until the project is initialized, because every following step writes into it. Once the project is initialized, its fields can no longer be edited.</p><h3 id="_2-provider" tabindex="-1">2. Provider <a class="header-anchor" href="#_2-provider" aria-label="Permalink to &quot;2. Provider&quot;">​</a></h3><p>Pick a <strong>Provider family</strong> (<code>claude</code>, <code>gemini</code>, <code>codex</code> or <code>mistral</code>), then <strong>Generate profile</strong>. Effortless writes an LLM routing profile from that family&#39;s preset. The button then becomes <strong>Regenerate profile</strong>. Optional.</p><h3 id="_3-stack" tabindex="-1">3. Stack <a class="header-anchor" href="#_3-stack" aria-label="Permalink to &quot;3. Stack&quot;">​</a></h3><p>The stack model picker: pick a model in <strong>Available models</strong>, check its build and cycle, fill in the <strong>Stack identifier</strong> and the required <strong>Variables</strong>, then <strong>Create the stack</strong>. The stack is created in the project you just initialized: this is how a module is declared (see <a href="/Effortless/en/guide/modules.html">Modules</a>). Optional.</p><h3 id="_4-scaffold" tabindex="-1">4. Scaffold <a class="header-anchor" href="#_4-scaffold" aria-label="Permalink to &quot;4. Scaffold&quot;">​</a></h3><p>The list of templates in the project store. Select one, then <strong>Apply template</strong>: it lays an initial structure at the project root. If the store is empty, the screen says so (&quot;No template in the project store.&quot;): skip the step. Optional.</p><h3 id="_5-deployment" tabindex="-1">5. Deployment <a class="header-anchor" href="#_5-deployment" aria-label="Permalink to &quot;5. Deployment&quot;">​</a></h3><p>A <strong>Recap</strong> lists the four previous steps, each followed by <strong>done</strong> or <strong>skipped</strong>: a step is “done” only when its action was actually performed (a stack created, for instance), not merely visited. Below it, the MCP &amp; Skills panel installs the Effortless server into your AI assistants, as in <strong>Preferences</strong> › <strong>MCP &amp; Skills</strong> (<a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>).</p><h2 id="finish" tabindex="-1">Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;Finish&quot;">​</a></h2><p><strong>Finish</strong> takes you back to the picker, without opening the project. Open it afterwards with <strong>Open…</strong>, or by typing its path.</p><p><strong>Cancel</strong> leaves the assistant at any time. What has already run (initialization, profile, stack, template) stays written in the folder.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>The same steps exist as MCP verbs: <code>effortless_init</code>, <code>effortless_provider_profile_init</code>, <code>effortless_stack_add</code>, <code>effortless_scaffold_apply_project</code> and <code>effortless_deploy</code>.</p>',21))])}const b=a(d,[["render",c]]);export{y as __pageData,b as default};
